INSERT INTO `carrier_frequency_bands` VALUES (1,'ntc','Band n78 (3500MHz)','5G Sub-6','3500 MHz (C-Band)','High-density urban speed layer. Official NTC trial towers in Sundhara, Babarmaal & Chhauni.','Trial Live',1,1,'2026-09-15 05:16:01','2026-09-15 05:16:01'),(2,'ntc','Band 3 (1800MHz)','4G LTE FDD','1800 MHz (Band 3)','Primary nationwide 4G LTE backbone across all 77 districts of Nepal.','Commercial Primary',1,2,'2026-09-15 05:16:01','2026-09-15 05:16:01'),(3,'ntc','Band 8 (900MHz)','4G LTE FDD','900 MHz (Band 8)','Sub-1GHz rural coverage, deep indoor wall penetration, and highway connectivity.','Commercial',1,3,'2026-09-15 05:16:01','2026-09-15 05:16:01'),(4,'ntc','Band 20 (800MHz)','4G LTE FDD','800 MHz (Band 20)','Ultra-rural mountain valley cellular propagation in remote geographic zones.','Commercial',1,4,'2026-09-15 05:16:01','2026-09-15 05:16:01'),(5,'ncell','Band 3 (1800MHz)','4G LTE FDD','1800 MHz (Band 3)','Primary Ncell 4G high-capacity metro coverage across major commercial cities.','Commercial Primary',1,5,'2026-09-15 05:16:01','2026-09-15 05:16:01'),(6,'ncell','Band 8 (900MHz)','4G LTE FDD','900 MHz (Band 8)','Sub-1GHz coverage for reliable indoor building penetration and suburban reach.','Commercial',1,6,'2026-09-15 05:16:01','2026-09-15 05:16:01'),(7,'ncell','Band 1 (2100MHz)','4G / 3G','2100 MHz (Band 1)','Supplementary high-bandwidth data layer refarmed from legacy 3G allocations.','Commercial',1,7,'2026-09-15 05:16:01','2026-09-15 05:16:01');
/*!40000 ALTER TABLE `carrier_frequency_bands` ENABLE KEYS */;
