DROP TABLE IF EXISTS `rival_matchups`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `rival_matchups` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `subtitle` varchar(255) DEFAULT NULL,
  `category_slug` varchar(255) NOT NULL,
  `device_a_id` bigint(20) unsigned DEFAULT NULL,
  `device_b_id` bigint(20) unsigned DEFAULT NULL,
  `metrics` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metrics`)),
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rival_matchups_device_a_id_foreign` (`device_a_id`),
  KEY `rival_matchups_device_b_id_foreign` (`device_b_id`),
  CONSTRAINT `rival_matchups_device_a_id_foreign` FOREIGN KEY (`device_a_id`) REFERENCES `gadgets` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rival_matchups_device_b_id_foreign` FOREIGN KEY (`device_b_id`) REFERENCES `gadgets` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

