INSERT INTO `rival_matchups` VALUES (1,'Ultra Flagship Smartphone Showdown','Latest hot flagships compared head-to-head on Nepal pricing & benchmarks','mobile',2,4,'[{\"label\":\"Performance & NPU\",\"left_val\":\"9.8 \\/ 10\",\"right_val\":\"9.7 \\/ 10\",\"left_pct\":52,\"right_pct\":48},{\"label\":\"Camera & Optics\",\"left_val\":\"50MP Triple Array\",\"right_val\":\"48MP ProRAW\",\"left_pct\":50,\"right_pct\":50},{\"label\":\"Battery & Fast Charge\",\"left_val\":\"5000mAh \\u00b7 45W\",\"right_val\":\"4422mAh \\u00b7 27W\",\"left_pct\":54,\"right_pct\":46},{\"label\":\"Display & LTPO\",\"left_val\":\"120Hz Dynamic AMOLED\",\"right_val\":\"120Hz ProMotion\",\"left_pct\":50,\"right_pct\":50},{\"label\":\"Nepal Value Score\",\"left_val\":\"9.4 \\/ 10\",\"right_val\":\"9.1 \\/ 10\",\"left_pct\":51,\"right_pct\":49}]',1,1,'2026-09-15 05:16:01','2026-09-15 05:16:01'),(2,'Hot Ultrabook Showdown','Top portable computing powerhouses evaluated for Nepali professionals & students','laptop',7,8,'[{\"label\":\"CPU Architecture\",\"left_val\":\"Intel Core Ultra\",\"right_val\":\"Apple M3 Pro\",\"left_pct\":48,\"right_pct\":52},{\"label\":\"Display Quality\",\"left_val\":\"3K Dynamic AMOLED\",\"right_val\":\"Liquid Retina XDR\",\"left_pct\":50,\"right_pct\":50},{\"label\":\"Battery Endurance\",\"left_val\":\"16 Hrs Productivity\",\"right_val\":\"22 Hrs All-Day\",\"left_pct\":45,\"right_pct\":55},{\"label\":\"Build & Portability\",\"left_val\":\"Ultra-thin 1.23kg\",\"right_val\":\"Unibody 1.62kg\",\"left_pct\":55,\"right_pct\":45},{\"label\":\"Nepal Value Score\",\"left_val\":\"9.2 \\/ 10\",\"right_val\":\"9.0 \\/ 10\",\"left_pct\":51,\"right_pct\":49}]',1,2,'2026-09-15 05:16:01','2026-09-15 05:16:01');
