DROP TABLE IF EXISTS `system_modules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `system_modules` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `code` varchar(255) NOT NULL,
  `route` varchar(255) DEFAULT NULL,
  `order` int(11) NOT NULL DEFAULT 1,
  `icon` varchar(255) DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'active',
  `parent_id` bigint(20) unsigned DEFAULT NULL,
  `sub_parent_id` bigint(20) unsigned DEFAULT NULL,
  `show_in_menu` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `system_modules_code_unique` (`code`),
  KEY `system_modules_sub_parent_id_foreign` (`sub_parent_id`),
  KEY `system_modules_status_show_in_menu_order_index` (`status`,`show_in_menu`,`order`),
  KEY `system_modules_parent_id_index` (`parent_id`),
  CONSTRAINT `system_modules_parent_id_foreign` FOREIGN KEY (`parent_id`) REFERENCES `system_modules` (`id`) ON DELETE SET NULL,
  CONSTRAINT `system_modules_sub_parent_id_foreign` FOREIGN KEY (`sub_parent_id`) REFERENCES `system_modules` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

