DROP TABLE IF EXISTS `upcoming_launches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `upcoming_launches` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `gadget_id` bigint(20) unsigned DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `brand` varchar(255) NOT NULL,
  `category` varchar(255) DEFAULT 'Smartphones',
  `expected_date` varchar(255) NOT NULL,
  `est_price` varchar(255) DEFAULT 'TBA',
  `confidence` tinyint(3) unsigned NOT NULL DEFAULT 90,
  `badge` varchar(255) DEFAULT NULL,
  `highlight` text DEFAULT NULL,
  `tag_color` varchar(255) NOT NULL DEFAULT 'emerald',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` smallint(5) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `upcoming_launches_gadget_id_foreign` (`gadget_id`),
  CONSTRAINT `upcoming_launches_gadget_id_foreign` FOREIGN KEY (`gadget_id`) REFERENCES `gadgets` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=102 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

